    "pub_date": "2026-08-10 14:48:05",
    "author": "",
    "description": "中新网8月10日电 据国家市场监督管理总局网站消息，近日，市场监管总局、工业和信息化部联合印发通知，公开征集2026年度计量支撑产业新质生产力发展项目。此举旨在深入贯彻落实《计量支撑产业新质生产力发展行动方案(2025—2030年)》部署要求，围绕战略性新兴产业和未来产业新质生产力发展迫切需求，持续发挥计量在科技创新、产业升级中的基础性、战略性作用，加快破解产业发展关键计量技术瓶颈，推动产业高质量发展。",
    "content": "中新网8月10日电 据国家市场监督管理总局网站消息，近日，市场监管总局、工业和信息化部联合印发通知，公开征集2026年度计量支撑产业新质生产力发展项目。此举旨在深入贯彻落实《计量支撑产业新质生产力发展行动方案(2025—2030年)》部署要求，围绕战略性新兴产业和未来产业新质生产力发展迫切需求，持续发挥计量在科技创新、产业升级中的基础性、战略性作用，加快破解产业发展关键计量技术瓶颈，推动产业高质量发展。"
