    "content": "新华社多哈8月10日电（记者汪强）卡塔尔国土面积仅1.15万平方公里、人口不足300万，却是中东地区举足轻重的危机斡旋方。在地区持续动荡的背景下，这个海湾国家近年来奉行平衡外交政策，在美国与伊朗、以色列与巴勒斯坦伊斯兰抵抗运动（哈马斯）等冲突方之间穿梭斡旋，以期将外交影响力转化为国家安全与战略资源。 地缘困局与战略抉择 卡塔尔地处海湾战略要冲，北部隔海与伊朗相望，南部与沙特阿拉伯接壤，处于中东主要力量交汇地带。与沙特、伊朗等地区大国相比，卡塔尔无论国土面积、人口规模还是军事力量都相对有限，但因丰富的天然气储备而极具…"
