    "link": "https://36kr.com/newsflashes/3933320103411079?f=rss",
    "pub_date": "2026-08-10 14:20:07",
    "author": "",
    "description": "36氪获悉，根据TrendForce集邦咨询最新手机产业研究，由于以存储器为首的零部件价格上涨，推升Apple（苹果）将发布的iPhone 18系列整机成本。以该系列的256GB版本BOM（物料清单）成本为例，预估年增幅度达38%左右，整机售价势必提高。为避免影响消费者购买意愿，Apple可能借由降低毛利的方式控制售价涨幅，以换取市占扩张。",
    "content": "36氪获悉，根据TrendForce集邦咨询最新手机产业研究，由于以存储器为首的零部件价格上涨，推升Apple（苹果）将发布的iPhone 18系列整机成本。以该系列的256GB版本BOM（物料清单）成本为例，预估年增幅度达38%左右，整机售价势必提高。为避免影响消费者购买意愿，Apple可能借由降低毛利的方式控制售价涨幅，以换取市占扩张。"
