    "content": "中国黄金可溯源投资金条。澎湃新闻记者赵利新图 金条表面有一个如指甲盖大小的二维码，只需用手机一扫，立马就会出现这个金条从产地到销售的全流程信息。 8月8日，中国黄金集团旗下中国黄金集团黄金珠宝股份有限公司（下称中金珠宝）在北京举办首届媒体开放日，宣布全品类投资金条已全面落地溯源码技术。澎湃新闻记者在现场看到了中金珠宝今年5月份联合国家金银制品质量检验检测中心（南京）（下称南京国检）正式发布的全新升级的可溯源投资金条。 可溯源投资金条的实用性究竟如何？会给黄金行业带来怎样的改变？业内如何看待黄金可溯源体系的前景？澎湃…"
