    "title": "泰国暖武里府行政组织办公楼发生枪击，主席重伤",
    "link": "https://m.thepaper.cn/detail/33751989",
    "pub_date": "2026-08-10 14:03:39",
    "author": "赵彩琳、常天童/新华社",
    "description": "据泰国媒体10日报道，暖武里府行政组织办公楼内当天上午发生枪击，该府行政组织主席通猜头部中弹。 报道说，枪击发生于当地时间11时左右。通猜伤势严重，他的私人司机也在事件中受伤，二人已被送往医院救治。 据悉，嫌疑人已向警方投降。警方正在现场调查案件详情。",
