    "content": "记者今天（10日）从市场监管总局了解到，近年来，全国机动车保有量持续增长，下沉市场出行需求旺盛，但部分县域及三、四线城市驾培行业滋生抱团涨价、协会串谋、收费失规、培训缩水等乱象，成为群众反映强烈的民生痛点。 《中国反垄断执法年度报告（2025）》指出，部分县域和三、四线城市驾培领域，竞争对手“抱团涨价”，行业协会以“行业自律”为名组织签订垄断协议，统一抬价、压缩教学服务，破坏公平竞争秩序，加重学员负担。 2022年至今，全国市场监管部门累计办结、在办驾培垄断案件12件，覆盖10余个省份，西南、西北地区县域为高发区域…"
