    "author": "陈立希",
    "description": "新华社北京8月10日电 美国是否会授权乌克兰生产“爱国者”防空系统拦截弹，近期备受舆论关注。美国《大西洋》杂志9日报道，美国两家军工企业将正式向美国政府说明它们在相关生产技术转让和知识产权风险方面的担忧。 这两家军工企业均生产“爱国者”拦截弹。美国国会消息人士说，这两家企业真正担心的是，乌克兰将对拦截弹作出改进，而后以更快速度更低造价大批量生产。这是美国当前生产线无法办到的。 现阶段，乌克兰要求获得更多拦截弹，以满足防空需求；美国被曝在…",
    "content": "新华社北京8月10日电 美国是否会授权乌克兰生产“爱国者”防空系统拦截弹，近期备受舆论关注。美国《大西洋》杂志9日报道，美国两家军工企业将正式向美国政府说明它们在相关生产技术转让和知识产权风险方面的担忧。 这两家军工企业均生产“爱国者”拦截弹。美国国会消息人士说，这两家企业真正担心的是，乌克兰将对拦截弹作出改进，而后以更快速度更低造价大批量生产。这是美国当前生产线无法办到的。 现阶段，乌克兰要求获得更多拦截弹，以满足防空需求；美国被曝在伊朗战事中大量消耗该型拦截弹，自顾不暇；美国的海湾和欧洲盟友基于自身需求，要么看…"
