    "pub_date": "2026-08-10 13:43:33",
    "author": "",
    "description": "中新网8月10日电 据日本《每日新闻》报道，日本长崎遭原子弹轰炸81周年纪念仪式9日在长崎市和平纪念公园举行。日本首相高市早苗参加仪式，其致辞时对“无核三原则”仍含糊表态，未明确表示日本将继续坚持该原则。此举进一步引发日本民众广泛担忧。",
    "content": "中新网8月10日电 据日本《每日新闻》报道，日本长崎遭原子弹轰炸81周年纪念仪式9日在长崎市和平纪念公园举行。日本首相高市早苗参加仪式，其致辞时对“无核三原则”仍含糊表态，未明确表示日本将继续坚持该原则。此举进一步引发日本民众广泛担忧。"
