    "content": "就宁波一车辆在充电站发生起火事件，@极氪服务 8月9日深夜发布《关于宁波一充电场站车辆过热的情况说明》： 8月9日，宁波市海曙区某充电场站，该司一车辆发生过热事件。消防部门第一时间到达现场并妥善处置，事故未造成人员伤亡。 获悉情况后，极氪第一时间安排工作人员赶赴现场，并成立专项工作组协助处理后续事宜。经初步核实，该车辆近期曾发生严重碰撞事故，事故发生后未通过品牌官方授权服务中心进行检测及维修。 目前，极氪正积极配合消防及相关部门开展现场勘验和事故原因调查。具体原因，以相关部门最终调查结论为准。 近日，一段车辆起火视…"
