    "content": "新华社北京8月10日电 题：以科学的思想方法推进管党治党——习近平党建思想理论品格系列述评之六 新华社记者施雨岑、孙少龙、王明玉 事必有法，然后可成。 习近平党建思想科学回答“建设什么样的长期执政的马克思主义政党、怎样建设长期执政的马克思主义政党”这一重大时代课题，既是认识论，又是方法论，蕴含着丰富的政治智慧和策略方法，彰显了科学的思想方法这一鲜明的理论品格。 学习好、贯彻好习近平党建思想，必须深刻把握贯穿其中的科学的思想方法，解放思想、实事求是、与时俱进，在实践、认识、再实践、再认识的螺旋式上升中，持之以恒推进党…"
