    "title": "文学花边特别节目 | 对话叶兆言：我为什么还在努力写",
    "link": "https://m.thepaper.cn/detail/33750719",
    "pub_date": "2026-08-10 12:09:01",
    "author": "澎湃新闻记者 罗昕 实习生 郑博文",
    "description": "8月14日上午，2026上海书展期间，叶兆言将走进澎湃新闻，围绕“我为什么还在努力写”接受澎湃新闻·文学花边独家专访。 在文坛，叶兆言的“劳模”之称由来已久。 他于1980年代初期开始文学创作。主要作品有八卷本《叶兆言中篇小说系列》，五卷本《叶兆言短篇小说编年》，长篇小说《一九三七年的爱情》《花煞》《别人的爱情》《没有玻璃的花房》《我们的心多么顽固》《很久以来》《刻骨铭心》《仪凤之门》《璩家花园》等，散文集“一叶知百年·叶兆言经典”（《…",
    "content": "8月14日上午，2026上海书展期间，叶兆言将走进澎湃新闻，围绕“我为什么还在努力写”接受澎湃新闻·文学花边独家专访。 在文坛，叶兆言的“劳模”之称由来已久。 他于1980年代初期开始文学创作。主要作品有八卷本《叶兆言中篇小说系列》，五卷本《叶兆言短篇小说编年》，长篇小说《一九三七年的爱情》《花煞》《别人的爱情》《没有玻璃的花房》《我们的心多么顽固》《很久以来》《刻骨铭心》《仪凤之门》《璩家花园》等，散文集“一叶知百年·叶兆言经典”（《陈旧人物 陈年旧事》《杂花生树 群莺乱飞》）等，城市系列《南京人》《南京传》《江…"
