    "content": "当地时间7月24日，埃隆·马斯克在得州的特斯拉超级工厂接受了《经济学人》主编扎妮·明顿·贝多斯的采访。在长达85分钟的采访视频中，马斯克与贝多斯围绕AI行业的未来发展、马斯克本人的政治参与，以及对未来社会的预测等多方面展开对谈。 本次对谈中较为激烈的争论，则涉及马斯克对于欧洲以及英国的预测。贝多斯表示，根据马斯克的发帖记录，后者相当关注欧洲，并指出马斯克所支持的并非仅仅是民粹主义右翼，还有在一些国家相当边缘的极右翼政党。马斯克随即表示，自己支持普通人，并强调了三条原则：国家应该拥有安全的边境、安全的城市，以及合理的…"
