    "content": "新华社华盛顿8月9日电 美国阿克西奥斯新闻网站9日报道称，美国总统特朗普在接受其采访时，倾向于对伊朗施加经济压力，而非发动新的军事行动。 特朗普在此次简短电话采访中表示，“我们正在低调处理此事”。“我们只是与他们（伊朗）进行半正式谈判。我们只是在观望伊朗，他们（面临）严重的通货膨胀以及没钱的事实。”他强调，美国的海上封锁令伊朗的经济雪上加霜。 特朗普还说，随着油价降至略高于每桶75美元，美国消费者从战事中感受到的痛苦有所减少。谈及与伊朗的反复博弈，“事情会解决的。它总能解决。这就像下棋一样”。 伊朗外交部长阿拉格齐…"
