    "title": "欧盟机构：7月全球海洋表面温度创新高",
    "link": "http://www.news.cn/20260810/c94a6fc6f684455dbfeab39653f45c5b/c.html",
    "pub_date": "2026-08-10 11:09:17",
    "author": "张馨文,张兆卿",
    "description": "新华社布鲁塞尔8月10日电（记者张馨文 张兆卿）欧盟气候监测机构哥白尼气候变化服务局10日发布的公报显示，今年7月全球海洋表面温度创下有记录以来同期最高值。 公报说，数据显示，7月南北纬60度之间极地外海域平均海洋表面温度达到20.96摄氏度，超过2023年7月创下的最高纪录20.89摄氏度。热带太平洋地区大范围海域水温异常偏高，厄尔尼诺状态已在该区域发展，预计未来数月还将进一步增强。 公报说，从全球看，今年7月与2024年7月并列成为…",
    "content": "新华社布鲁塞尔8月10日电（记者张馨文 张兆卿）欧盟气候监测机构哥白尼气候变化服务局10日发布的公报显示，今年7月全球海洋表面温度创下有记录以来同期最高值。 公报说，数据显示，7月南北纬60度之间极地外海域平均海洋表面温度达到20.96摄氏度，超过2023年7月创下的最高纪录20.89摄氏度。热带太平洋地区大范围海域水温异常偏高，厄尔尼诺状态已在该区域发展，预计未来数月还将进一步增强。 公报说，从全球看，今年7月与2024年7月并列成为有记录以来第二热的7月，仅次于2023年。7月全球平均地表气温为16.9摄氏度，…"
