    "content": "新华社华盛顿8月9日电 美国媒体9日援引一名美国高级官员的话报道称，白宫“并不在意”以色列总理内塔尼亚胡拒绝接受加沙和平计划，并称他的这一表态是出于选举周期中的“政治需要”。 美国阿克西奥斯新闻网站记者巴拉克·拉维德当天在社交媒体上发布帖文称，这名高级官员告诉他，白宫“理解内塔尼亚胡的政治需要”。这名官员说，“我们对此没有意见，只要他（内塔尼亚胡）继续按我们的要求行事——尤其是克制对加沙的打击。” 帖文还援引另一名美国官员的消息称，内塔尼亚胡上周同美国总统特朗普女婿库什纳通电话时说，尽管他持怀疑态度，但仍“愿意给‘…"
