    "author": "冯家顺",
    "description": "新华社北京8月10日电（记者冯家顺）记者8月10日从最高人民法院获悉，广州海事法院近日成功审理并调解一起发生在霍尔木兹海峡的外籍船舶碰撞纠纷案，充分展示了中国海事审判的公正专业和高效便捷。 据了解，“阿达琳”轮和“前线老鹰”轮于2025年6月在霍尔木兹海峡附近海域碰撞后，外籍当事人一致同意适用我国法律，由广州海事法院解决双方实体争议。 广州海事法院在扣押船舶、庭前会议、设立基金、开庭审理、技术事实核查、开展司法调解等多个环节，展现了中国…",
    "content": "新华社北京8月10日电（记者冯家顺）记者8月10日从最高人民法院获悉，广州海事法院近日成功审理并调解一起发生在霍尔木兹海峡的外籍船舶碰撞纠纷案，充分展示了中国海事审判的公正专业和高效便捷。 据了解，“阿达琳”轮和“前线老鹰”轮于2025年6月在霍尔木兹海峡附近海域碰撞后，外籍当事人一致同意适用我国法律，由广州海事法院解决双方实体争议。 广州海事法院在扣押船舶、庭前会议、设立基金、开庭审理、技术事实核查、开展司法调解等多个环节，展现了中国海事法院驾驭复杂疑难海事案件的司法能力和高效务实的司法作风，赢得外方当事人的充分…"
