    "description": "新华社北京8月10日电（记者李佳巍、李志浩）炎炎夏日，各类西瓜集中上市。在空调房里吃西瓜，是众多网友夏天最治愈的快乐。令许多人意想不到的是，甜蜜的西瓜不仅爽口好吃，居然还低糖低脂，含糖量也处于常见水果中较低水平。 不仅健康人群可以大快朵颐，部分高血压、糖尿病患者也可遵医嘱适量“解馋”，西瓜因此获得“报恩水果”的美名。一起听听专家怎么说。 在安徽省亳州市利辛县永兴镇诸王社区青少年活动中心，小朋友在吃西瓜。新华社发（刘勤利摄） 甜蜜的西瓜竟…",
    "content": "新华社北京8月10日电（记者李佳巍、李志浩）炎炎夏日，各类西瓜集中上市。在空调房里吃西瓜，是众多网友夏天最治愈的快乐。令许多人意想不到的是，甜蜜的西瓜不仅爽口好吃，居然还低糖低脂，含糖量也处于常见水果中较低水平。 不仅健康人群可以大快朵颐，部分高血压、糖尿病患者也可遵医嘱适量“解馋”，西瓜因此获得“报恩水果”的美名。一起听听专家怎么说。 在安徽省亳州市利辛县永兴镇诸王社区青少年活动中心，小朋友在吃西瓜。新华社发（刘勤利摄） 甜蜜的西瓜竟是低糖、低热量的水果代表 西瓜甜度高，许多人想当然地认为含糖量、热量也高。北京大…"
