    "description": "妈妈给他算了一笔账：数学和物理都不是他的强项，走普高大概率转文科，出路窄。更重要的是，三年后能否考上理想的大学，他心里也没底。而选择中本贯通，不用经历高中三年的残酷厮杀就能进入本科院校，学一门技术，还能拿本科学历。 南方周末记者 魏翠翠 南方周末实习生 周语萌 责任编辑：杜茂林 2026年7月25日，广州报业文化中心采编中心一楼，广州市高中阶段学校补录招生咨询会现场。其中，中本贯通有6个专业参与补录，共57个补录名额。（南方周末记者 魏…",
    "content": "妈妈给他算了一笔账：数学和物理都不是他的强项，走普高大概率转文科，出路窄。更重要的是，三年后能否考上理想的大学，他心里也没底。而选择中本贯通，不用经历高中三年的残酷厮杀就能进入本科院校，学一门技术，还能拿本科学历。 对一个15岁的孩子来说，七年锁定一个专业，本身就是一种风险。“初中毕业生对未来认知未必清晰，选了后发现不适合，怎么办？” 南方周末记者 魏翠翠 南方周末实习生 周语萌 责任编辑：杜茂林 2026年7月25日，广州报业文化中心采编中心一楼，广州市高中阶段学校补录招生咨询会现场。其中，中本贯通有6个专业参与…"
