    "content": "2026年08月10日 省界牌附近的巴蜀雅楠景区里，野生金丝楠木林吸引着游客慕名而来。一座新落成的“连心桥”穿河而过，勾连起川渝两地的田埂与院落。 今年，《四川省安岳县双龙街乡孔雀村、重庆市大足区高坪镇茨竹村村庄规划（2024—2035年）》在两地正式获批，成为全国首个跨省级行政区联合编制的村庄规划。从行政边界转为合作前沿，从“各管一摊”变成“共绘蓝图”，川渝两村规划先行、协同发力，走出了一条毗邻乡村共赴振兴的发展新路。 规划先行，协同破解堵点 茨竹村与孔雀村山水相连、人文相亲，但以往却在发展上“各吹各号”。 “基…"
