    "author": "",
    "description": "2026年08月10日 某单位拟提拔一位同志任纪委书记，上级想了解其斗争精神强不强，有同志回答：“他善于斗争”。上级听懂了“弦外之音”，严肃指出，武松打虎不是因为“会”才打的，首先是“敢”打。 敢于斗争和善于斗争缺一不可，而敢于斗争处于优先位置。片面、割裂地理解斗争精神，在认识上是错误的，在实践中会产生严重后果。假如在事业需要的时候不能、不敢、不愿挺身而出，反而畏葸不前，或者做戏、打太极，就会极大地损害党和人民的事业，是绝对不允许的。 …",
    "content": "2026年08月10日 某单位拟提拔一位同志任纪委书记，上级想了解其斗争精神强不强，有同志回答：“他善于斗争”。上级听懂了“弦外之音”，严肃指出，武松打虎不是因为“会”才打的，首先是“敢”打。 敢于斗争和善于斗争缺一不可，而敢于斗争处于优先位置。片面、割裂地理解斗争精神，在认识上是错误的，在实践中会产生严重后果。假如在事业需要的时候不能、不敢、不愿挺身而出，反而畏葸不前，或者做戏、打太极，就会极大地损害党和人民的事业，是绝对不允许的。 敢于斗争是我们党的鲜明品格，是党和人民不可战胜的强大精神力量。然而现实中，一些领…"
