    "description": "2026年08月10日 今年第13号台风“白海豚”分别于8月9日17时30分前后、18时40分前后在浙江台州玉环市、浙江温州乐清市登陆。为应对台风“白海豚”，玉环市严格执行包保责任制，采取“属地全面排查、部门条块普查、防指综合督导”模式，开展全域拉网式排查整治，分层分类分级管控风险。乐清市全面复核辖区人员底数，同时细化制定人员转移梯次方案，全市共设置避灾场所345处、临时避灾点58处，并提前备足72小时生活物资。 图为8月9日，乐清市清…",
    "content": "2026年08月10日 今年第13号台风“白海豚”分别于8月9日17时30分前后、18时40分前后在浙江台州玉环市、浙江温州乐清市登陆。为应对台风“白海豚”，玉环市严格执行包保责任制，采取“属地全面排查、部门条块普查、防指综合督导”模式，开展全域拉网式排查整治，分层分类分级管控风险。乐清市全面复核辖区人员底数，同时细化制定人员转移梯次方案，全市共设置避灾场所345处、临时避灾点58处，并提前备足72小时生活物资。 图为8月9日，乐清市清江镇的党员干部转移行动不便的老人。 本报记者&nbsp;&nbsp;窦瀚洋文&n…"
