    "content": "2026年08月10日 雨后，位于广东广州黄埔区的极飞科技超级农场，弥漫着稻种的清香，一架黑色涂装的农业无人机贴着稻田低空掠过，半小时可完成300亩飞播。 “以前年轻人觉得种地又苦又土，现在不一样了。”极飞科技联合创始人龚槚钦指着屏幕上跳动的数据说，他们培养的14万名智慧农业人才，绝大多数是90后、00后。这些新农人回到村庄，办智慧农场、搞无人机种植，种地变成一件很“炫酷”的事。 “炫酷”因何而来？源自科技创新。 在极飞科技超级农场，农用机器人、土壤传感器、气象站、智能相机等物联网设备随处可见；每15分钟上传一次温…"
