    "description": "2026年08月10日 制图：王 鹏 \"> 以平台经济为代表的新就业形态近年来蓬勃发展，外卖骑手、快递员、网约车司机等新就业群体日益壮大。据国家统计局、人力资源和社会保障部相关数据，全国新就业形态劳动者已达8400万人。“十五五”规划纲要明确提出，“健全灵活就业、新就业形态劳动者权益保障制度”，“提高灵活就业人员、农民工、新就业形态人员参保率”。 由于工作的灵活性与不确定性，新就业群体的劳动保障不尽如人意，劳动关系不明、社保缴纳缺位、保…",
