    "author": "",
    "description": "2026年08月10日 近年来，网络平台已经成了不少消费者的购物首选，小到纸巾，大到生产机器，一键下单即可全国送达。然而，有读者反映，在平台消费后，开具发票成了难事：个别商家拖延甚至拒开发票，找平台不管，维权很麻烦。 今年4月，北京朝阳区读者潘先生在当当平台花21元下单了一本图书，他通过后台向商家索要发票，商家表示收货后才能开票。当潘先生确认收货后再次索要发票时，对方要么不回消息，要么就用机器人客服反复自动回复“客服已经下班”，变相拒开…",
    "content": "2026年08月10日 近年来，网络平台已经成了不少消费者的购物首选，小到纸巾，大到生产机器，一键下单即可全国送达。然而，有读者反映，在平台消费后，开具发票成了难事：个别商家拖延甚至拒开发票，找平台不管，维权很麻烦。 今年4月，北京朝阳区读者潘先生在当当平台花21元下单了一本图书，他通过后台向商家索要发票，商家表示收货后才能开票。当潘先生确认收货后再次索要发票时，对方要么不回消息，要么就用机器人客服反复自动回复“客服已经下班”，变相拒开发票。 无独有偶，网友王女士在人民网“人民投诉”平台投诉称，她在美团平台上花费5…"
